use std::io

fn find(keys: Vec<int>, k: int) -> int {
    let mut i = 0
    while i < keys.len() as int {
        if keys[i as usize] == k {
            return i
        }
        i += 1
    }
    -1
}

fn main() {
    let mut lines: Vec<string> = []
    loop {
        let l = io::read_line() ?? ""
        if l.len() == 0 {
            break
        }
        lines.push(l)
    }
    let mut cap = 1
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    let mut first = true
    for line in lines {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>() ?? 1
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>() ?? 0
            let v = parts[2].parse::<int>() ?? 0
            let idx = find(keys, k)
            if idx >= 0 {
                keys.remove(idx as usize)
                vals.remove(idx as usize)
            }
            keys.insert(0, k)
            vals.insert(0, v)
            if keys.len() as int > cap {
                let last = keys.len() - 1
                let ek = keys[last]
                keys.remove(last)
                vals.remove(last)
                println("evict ${ek}")
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>() ?? 0
            let idx = find(keys, k)
            if idx < 0 {
                println("-1")
            } else {
                let v = vals[idx as usize]
                keys.remove(idx as usize)
                vals.remove(idx as usize)
                keys.insert(0, k)
                vals.insert(0, v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i = 0
                while i < keys.len() {
                    if i > 0 {
                        out = out + " "
                    }
                    out = out + "${keys[i]}"
                    i += 1
                }
                println(out)
            }
        }
    }
}

